import{_ as o,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"篇784｜超脱者与制度·总论——超脱者在文明制度中的位置","description":"","frontmatter":{"title":"篇784｜超脱者与制度·总论——超脱者在文明制度中的位置","no":784,"module":4,"tags":["超脱","制度","总论","锚点共生","治理框架"],"related":["0040-共生宪法总纲","0049-治理框架与权力制衡","701-超脱正统定义总论"]},"headers":[],"relativePath":"zh/0784_模块4-制度-总论.md","filePath":"zh/0784_模块4-制度-总论.md"}'),n={name:"zh/0784_模块4-制度-总论.md"};function e(i,t,s,u,h,g){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="篇784-超脱者与制度·总论——超脱者在文明制度中的位置" tabindex="-1">篇784｜超脱者与制度·总论——超脱者在文明制度中的位置 <a class="header-anchor" href="#篇784-超脱者与制度·总论——超脱者在文明制度中的位置" aria-label="Permalink to &quot;篇784｜超脱者与制度·总论——超脱者在文明制度中的位置&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档40、49、701</p></blockquote><h2 id="引言-最强的人-站在制度的哪一边" tabindex="-1">引言：最强的人，站在制度的哪一边 <a class="header-anchor" href="#引言-最强的人-站在制度的哪一边" aria-label="Permalink to &quot;引言：最强的人，站在制度的哪一边&quot;">​</a></h2><p>旧世界的超脱者永远在制度之上。天帝不守法、仙帝不遵规、宇宙主宰不进法院——他已经最强了，制度管不着他。衡元宙必须正面回答：<strong>一个强到衡锚超多元境的人，在锚点共生文明的制度里，到底站在什么位置？</strong> 本篇作为&quot;超脱者与制度&quot;这一组的总论，要把这个位置钉死。答案是：<strong>他不站在制度之上，他站在制度之中。</strong></p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求制度位置不含掠夺；万族共和公理要求制度对超脱者和万族平等；集体升维公理要求制度位置服务于共同升维；因果自律公理要求制度位置不制造因果漏洞；法则优先公理要求制度位置在法则层面自洽、不可被超脱者个人改写。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、旧世界的三种-制度外-位置" tabindex="-1">一、旧世界的三种&quot;制度外&quot;位置 <a class="header-anchor" href="#一、旧世界的三种-制度外-位置" aria-label="Permalink to &quot;一、旧世界的三种&quot;制度外&quot;位置&quot;">​</a></h2><p>旧世界的超脱者与制度的关系，万变不离三种：</p><ol><li><strong>制度之上</strong>：超脱者就是制度本身，他说的话就是法。代表：石昊、各类天帝</li><li><strong>制度之外</strong>：超脱者超越了制度，制度管不着他。代表：纪宁式闭关养老</li><li><strong>制度之内但特权化</strong>：超脱者表面守法，实际上制度为他开后门。代表：各类&quot;主角法外开恩&quot;</li></ol><p>三种位置看起来不同，本质一样——<strong>超脱者和普通人不在同一条法律线上。</strong> 制度对他要么不存在，要么是他的工具。</p><h2 id="二、衡元宙的新位置-制度之内-平等适用" tabindex="-1">二、衡元宙的新位置：制度之内，平等适用 <a class="header-anchor" href="#二、衡元宙的新位置-制度之内-平等适用" aria-label="Permalink to &quot;二、衡元宙的新位置：制度之内，平等适用&quot;">​</a></h2><p>锚点共生文明给出的新位置，把三种旧位置全部废除：</p><blockquote><p><strong>超脱者在制度之内，与万族一切生灵适用同一部法律。他没有法外特权，没有制度豁免，他的每一份权力都是制度授予的、可被制度收回的。</strong></p></blockquote><p>这个新位置有三个构件：</p><ul><li><strong>同法</strong>：超脱者违反万族法律，和万族任何生灵走同一程序、受同一制裁。不存在&quot;超脱者特赦&quot;</li><li><strong>同责</strong>：超脱者造成的因果损害，由他自己承担，不允许&quot;我是为你好&quot;来抵消</li><li><strong>同权</strong>：超脱者在锚点议事会里只有一票，和万族代表平票。他的&quot;强&quot;不给他额外权力</li></ul><p>三个构件叠加，把超脱者从&quot;制度外的超人&quot;变成&quot;制度内的公民&quot;——一个恰好算力大一万倍的公民。</p><h2 id="三、制度位置的三个后果" tabindex="-1">三、制度位置的三个后果 <a class="header-anchor" href="#三、制度位置的三个后果" aria-label="Permalink to &quot;三、制度位置的三个后果&quot;">​</a></h2><p>把超脱者放进制度之内，产生三个硬后果：</p><ol><li><strong>超脱者不能造法</strong>：他可以提案，但不能自己立法。立法权在锚点议事会</li><li><strong>超脱者不能违法</strong>：他违法由共生法院审理，不受任何&quot;实力豁免&quot;</li><li><strong>超脱者不能废法</strong>：他不能因为某条法律&quot;不方便&quot;就废除它。修法走锚点议事会程序</li></ol><p>三个后果确保制度始终是万族的公共工具，不是超脱者的私人玩具。</p><h2 id="四、六篇子文章的定位预告" tabindex="-1">四、六篇子文章的定位预告 <a class="header-anchor" href="#四、六篇子文章的定位预告" aria-label="Permalink to &quot;四、六篇子文章的定位预告&quot;">​</a></h2><p>785至790六篇子文章，将逐一处理超脱者与四大制度机构的关系，以及两个横切问题：</p><ul><li><strong>锚点议事会</strong>（785）：超脱者在立法机构里是什么角色？</li><li><strong>共生执行委员会</strong>（786）：超脱者在行政机构里是什么角色？</li><li><strong>共生法院</strong>（787）：超脱者在司法机构里是什么角色？</li><li><strong>锚点监督委员会</strong>（788）：超脱者在监督机构里是什么角色？</li><li><strong>法律约束与豁免边界</strong>（789）：超脱者有没有任何法律豁免？豁免边界在哪？</li><li><strong>权力制衡机制</strong>（790）：四大机构怎么互相制衡，确保超脱者不把任何一个机构变成私人工具？</li></ul><p>六个维度合起来，就是&quot;超脱者在制度中&quot;的完整组织图。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：旧世界让最强者在制度外，等于让制度失去最强的执行者；衡元宙把超脱者拉进制度，让他的算力服务于制度运行</li><li><strong>反掠夺</strong>：制度外的超脱者天然是掠夺者——他没有约束；制度内的超脱者必须守法，掠夺路径被封死</li><li><strong>唐罗上限对比</strong>：唐罗在他的位面是&quot;制度本身&quot;，衡元宙要求超脱者只是制度内的一个岗位</li><li><strong>万族全覆盖</strong>：制度对万族一切生灵平等适用，超脱者不能例外</li><li><strong>超多元全开放</strong>：超脱者与制度关系的全部规则通过无私道全网开放，万族可查阅。超脱者在制度中的每一步操作都被阿赖耶网络+多层监督记录，文明权重实时反映其制度内表现</li><li><strong>全员无限均等</strong>：众生全员无限均等法则——锚点共生文明内人人自带基础无限之力，佛系懒狗保有保底基础无限、不被时代淘汰，卷王少年至尊可叠加更高层级无限；无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>最强的人，站在制度之中，不站在制度之上。这不是对超脱者的贬低，是对制度的尊重——一个好的制度，应该能管住任何人，包括最强的人。如果一个制度管不住最强的人，那它就不是制度，是给弱者套的枷锁。衡元宙不要那种枷锁，衡元宙要的是连超脱者都必须钻的笼子。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0040-共生宪法总纲.html">0040-共生宪法总纲</a> · <a href="./0049-治理框架与权力制衡.html">0049-治理框架与权力制衡</a> · <a href="./0701_模块4-超脱正统定义总论.html">701-超脱正统定义总论</a> · <a href="./0780_模块4-万族-超脱者的监督机制.html">780-超脱者的监督机制</a></li></ul>',30)])])}const d=o(n,[["render",e]]);export{p as __pageData,d as default};
